Use the **Claude API** (Anthropic Messages API). It accepts PDFs directly, including both digital text and scanned pages, so you don't need a separate OCR step, templates, or training. With structured outputs, it returns JSON that matches a schema you define. It's a single stateless HTTPS request per invoice, so 300 a week needs no queue or extra infrastructure.

Here it is in Python. The TypeScript SDK (`@anthropic-ai/sdk`) and raw `fetch` use the same request shape, so it ports directly to your app.

```python
"""
Invoice field extraction with the Claude API.

Setup:
    pip install anthropic
    export ANTHROPIC_API_KEY=sk-ant-...

Usage:
    python extract_invoice.py invoice.pdf

TypeScript port: `npm i @anthropic-ai/sdk`, then call client.messages.create
with the same model / messages / output_config payload shown below.
"""

import base64
import json
import mimetypes
import sys
from pathlib import Path

import anthropic

MODEL = "claude-opus-4-7"  # For high volume or lower cost, consider Sonnet or Haiku.

INVOICE_SCHEMA = {
    "type": "object",
    "properties": {
        "invoice_number": {"type": ["string", "null"]},
        "supplier": {"type": ["string", "null"]},
        "date": {
            "type": ["string", "null"],
            "description": "Invoice issue date in ISO 8601 format (YYYY-MM-DD)",
        },
        "total": {
            "type": ["number", "null"],
            "description": "Final amount due, including tax, as a plain number",
        },
        "currency": {
            "type": ["string", "null"],
            "description": "ISO 4217 code, e.g. USD, GBP, EUR",
        },
    },
    "required": ["invoice_number", "supplier", "date", "total", "currency"],
    "additionalProperties": False,
}

PROMPT = (
    "Extract the following fields from this invoice: invoice number, supplier "
    "(the company issuing the invoice, not the customer), invoice date, and the "
    "final total amount due (including tax). Use null for any field that is not "
    "present. Do not guess."
)

client = anthropic.Anthropic()  # reads ANTHROPIC_API_KEY


def _file_block(path: Path) -> dict:
    data = base64.standard_b64encode(path.read_bytes()).decode("utf-8")
    media_type = mimetypes.guess_type(path.name)[0] or "application/pdf"

    if media_type == "application/pdf":
        return {
            "type": "document",
            "source": {"type": "base64", "media_type": media_type, "data": data},
        }
    if media_type in ("image/jpeg", "image/png", "image/gif", "image/webp"):
        return {
            "type": "image",
            "source": {"type": "base64", "media_type": media_type, "data": data},
        }
    raise ValueError(f"Unsupported file type: {media_type}")


def extract_invoice(path: str | Path) -> dict:
    path = Path(path)
    response = client.messages.create(
        model=MODEL,
        max_tokens=1024,
        messages=[
            {
                "role": "user",
                "content": [_file_block(path), {"type": "text", "text": PROMPT}],
            }
        ],
        output_config={"format": {"type": "json_schema", "schema": INVOICE_SCHEMA}},
    )

    if response.stop_reason == "refusal":
        raise RuntimeError("Model declined to process this document.")
    if response.stop_reason == "max_tokens":
        raise RuntimeError("Response was truncated; increase max_tokens.")

    text = next(b.text for b in response.content if b.type == "text")
    return json.loads(text)


if __name__ == "__main__":
    if len(sys.argv) != 2:
        sys.exit("Usage: python extract_invoice.py <invoice.pdf|png|jpg>")
    try:
        result = extract_invoice(sys.argv[1])
        print(json.dumps(result, indent=2))
    except anthropic.APIStatusError as e:
        sys.exit(f"API error {e.status_code}: {e.message}")
```

Example output:

```json
{
  "invoice_number": "INV-20417",
  "supplier": "Northwind Office Supplies Ltd",
  "date": "2024-05-14",
  "total": 1284.5,
  "currency": "GBP"
}
```

Notes for your pilot:
- **Limits:** PDFs can be up to 32 MB and 600 pages per request, which covers invoices easily.
- **Validation:** Add light checks before you trust the data automatically. For example, flag `null` fields, parse the date, and confirm the total is above 0, then send flagged invoices to manual review during the pilot.
- **Retries:** The SDK automatically retries rate-limit errors (429) and server errors (5xx), so at your volume a direct synchronous call per upload is fine.

